    # crambin's cysteines pair up: Cys3-Cys40, Cys4-Cys32, Cys16-Cys26
    assert ("A", 40) in neighbours(TEXT, "A", 3)
    assert ("A", 26) in neighbours(TEXT, "A", 16)

